import{_ as a,o as e,c as d,ah as r}from"./chunks/framework.DuX8SFU5.js";const A=JSON.parse('{"title":"AM_CAN_BRIDGE — CAN-шлюз для систем управления машин","description":"","frontmatter":{"title":"AM_CAN_BRIDGE — CAN-шлюз для систем управления машин","device":{"name":"AM_CAN_BRIDGE","title":"CAN-шлюз для систем управления машин","summary":"Программный мост между двумя участками штатной CAN-сети. Подключает бортовой компьютер по Ethernet или CAN для обмена командами и телеметрией.","status":"development","image":"am_can_bridge_enclosure.webp","specs":["CAN0 IN / CAN0 OUT","CAN2","Ethernet 10/100","USB-C","24 В"],"order":2},"pdf":"/pdf/AM_CAN_BRIDGE_overview.pdf"},"headers":[],"relativePath":"am_can_to_can_bridge/index.md","filePath":"am_can_to_can_bridge/README.md"}'),n={name:"am_can_to_can_bridge/index.md"};function s(o,t,i,h,l,p){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h2 id="возможности" tabindex="-1">Возможности <a class="header-anchor" href="#возможности" aria-label="Permalink to &quot;Возможности&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>Возможности платформы</th></tr></thead><tbody><tr><td>Основной CAN-мост</td><td>2 отдельных сегмента, CAN0 IN и CAN0 OUT; пересылку кадров выполняет прошивка</td></tr><tr><td>Дополнительный CAN</td><td>Независимый интерфейс CAN2: бортовой компьютер, CAN-датчики или внешние модули ввода-вывода</td></tr><tr><td>Ethernet</td><td>10/100 Мбит/с, обмен с бортовым компьютером</td></tr><tr><td>USB-C</td><td>USB 2.0 Full Speed: сервисное подключение и питание системной электроники</td></tr><tr><td>Отключение входа</td><td>2 последовательных релейных каскада отключают CAN0 IN от приёмного узла шлюза</td></tr><tr><td>Диагностика питания</td><td>Измерение входного напряжения, контроль наличия основного и USB-питания</td></tr><tr><td>Основное питание</td><td>24 В номинально, с внешней защитой; рабочий диапазон уточняется для исполнения</td></tr><tr><td>Габариты платы</td><td>72,1 × 77,1 мм</td></tr></tbody></table><h2 id="режимы" tabindex="-1">Режимы <a class="header-anchor" href="#режимы" aria-label="Permalink to &quot;Режимы&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Режим прошивки</th><th>Действие с сообщениями</th></tr></thead><tbody><tr><td>Пересылка</td><td>Передача разрешённых кадров без изменения данных</td></tr><tr><td>Фильтрация</td><td>Передача или блокировка кадров по заданным правилам</td></tr><tr><td>Замена</td><td>Блокировка выбранного кадра и передача кадра с новым значением</td></tr><tr><td>Формирование</td><td>Создание сообщений по протоколу штатного узла</td></tr></tbody></table><p>Режимы реализуются в прошивке для конкретной машины: наличие интерфейсов не означает готового универсального преобразования протоколов. Аппаратного обхода CAN0 IN → CAN0 OUT при отключении питания нет. Возможно исполнение в корпусе под требования машины.</p><h2 id="протоколы" tabindex="-1">Протоколы <a class="header-anchor" href="#протоколы" aria-label="Permalink to &quot;Протоколы&quot;">​</a></h2><p>Шлюз связывает <strong>DroneCAN</strong>, <strong>CANopen</strong> и собственный протокол машины при разработке соответствующей прошивки. Согласуются идентификаторы, форматы, периодичность сообщений и реакции на потерю связи. Сквозная поддержка CAN FD не заявлена.</p><h2 id="схема-подключения" tabindex="-1">Схема подключения <a class="header-anchor" href="#схема-подключения" aria-label="Permalink to &quot;Схема подключения&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                 Бортовой компьютер</span></span>
<span class="line"><span>                         │ Ethernet или CAN2</span></span>
<span class="line"><span>                         ▼</span></span>
<span class="line"><span> Штатный CAN-джойстик ──► AM_CAN_BRIDGE ──► Штатный контроллер</span></span>
<span class="line"><span> или контроллер  CAN0 IN                CAN0 OUT   механизма</span></span></code></pre></div><p>CAN0 IN и CAN0 OUT образуют два отдельных сегмента. CAN2 также подходит для CAN-датчиков и модулей ввода-вывода.</p><h2 id="применение" tabindex="-1">Применение <a class="header-anchor" href="#применение" aria-label="Permalink to &quot;Применение&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Задача машины</th><th>Функция шлюза</th></tr></thead><tbody><tr><td>Автоматическая подача</td><td>Передача команды бортового компьютера штатному контроллеру подачи в формате его протокола</td></tr><tr><td>Ручной и автоматический режимы</td><td>Передача команд CAN-джойстика либо замена выбранных команд автоматикой; приоритет оператора задаётся в проекте</td></tr><tr><td>Регистрация параметров бурения</td><td>Передача доступных в CAN значений давления, частоты вращения и состояний на компьютер для записи и отображения</td></tr><tr><td>Дополнительные измерения</td><td>Получение данных от CAN-датчиков или внешнего узла ввода-вывода; формирование сообщений для системы управления машины</td></tr><tr><td>Согласование оборудования</td><td>Фильтрация и преобразование сообщений между сегментами; при необходимости воспроизведение сообщений штатного узла</td></tr></tbody></table><h2 id="условия-интеграции" tabindex="-1">Условия интеграции <a class="header-anchor" href="#условия-интеграции" aria-label="Permalink to &quot;Условия интеграции&quot;">​</a></h2><p><strong>Топология.</strong> Мост пересылает кадры программно: при потере питания или остановке прошивки обмен между сегментами прекращается. Каждому сегменту CAN нужна терминация по схеме сети; гальваническая изоляция не заявлена.</p><p><strong>Подключение.</strong> Вводы основного питания XT30, M8 и M12 электрически объединены: используется один внешний источник. USB не заявлен как хост для датчиков; аналоговые и дискретные датчики подключаются через внешний узел ввода-вывода.</p><p><strong>Режимы.</strong> Задержки, тайм-ауты, допустимые команды и поведение при отказах проверяются на машине. Релейное отключение входа не является сертифицированной функцией безопасности; аварийный останов выполняется независимой цепью.</p><h2 id="следующии-шаг" tabindex="-1">Следующий шаг <a class="header-anchor" href="#следующии-шаг" aria-label="Permalink to &quot;Следующий шаг&quot;">​</a></h2><p>Для интеграции нужны схема CAN-сети, описание сообщений и функции автоматики. Электрические параметры, диапазон температур и степень защиты корпуса согласуются для исполнения. Подробные характеристики и распиновка — в <a href="./datasheet">даташите</a>.</p>`,18)])])}const N=a(n,[["render",s]]);export{A as __pageData,N as default};
